import { useState, useEffect } from 'react';
export function useLocalStorage<T>(key: string, initialValue: T) {
  const [value, setValue] = useState<T>(() => {
    const stored = localStorage.getItem(key);
    return stored ? JSON.parse(stored) : initialValue;
  });
  useEffect(() => {
    localStorage.setItem(key, JSON.stringify(value));
  }, [key, value]);
  return [value, setValue] as const;
}

import express from 'express';
import multer from 'multer';
import pdf from 'pdf-parse';

const upload = multer({ storage: multer.memoryStorage() });
const router = express.Router();

router.post('/parse', upload.single('resume'), async (req, res) => {
  if (!req.file) return res.status(400).json({ error: 'No file uploaded' });
  try {
    const data = await pdf(req.file.buffer);
    const text = data.text.toLowerCase();
    // Basic extraction logic
    res.json({ extractedText: text });
  } catch (error) {
    res.status(500).json({ error: 'Parsing failed' });
  }
});
export default router;

import { useMemo } from 'react';

export const useResumeScanner = (resumeText: string, targetKeywords: string[]) => {
  return useMemo(() => {
    const found = targetKeywords.filter(keyword => 
      resumeText.includes(keyword.toLowerCase())
    );
    const missing = targetKeywords.filter(keyword => 
      !resumeText.includes(keyword.toLowerCase())
    );
    const score = targetKeywords.length > 0 
      ? Math.round((found.length / targetKeywords.length) * 100) 
      : 0;

    return { score, found, missing };
  }, [resumeText, targetKeywords]);
};
